    private static final Set<String> INSTRUCTIONS=Set.of("RENEW_PRINCIPAL","RENEW_PRINCIPAL_PAY_PROFIT","PAY_TO_ACCOUNT","CLOSE_AND_SETTLE","WAIT_INSTRUCTION");
    private static final Set<String> SOURCES=Set.of("CUSTOMER","PRODUCT_DEFAULT","ACCOUNT_SERVICING");
