    @Transactional
    public TermActionResponse requestEarlyTermination(long accountId,EarlyTerminationRequest request,String actor,String correlationId,String idempotencyKey){
        AccountRow a=requireTermAccount(accountId,true);TermLock t=requireTerm(accountId);if(!"ACTIVE".equals(upper(a.status())))throw lifecycle("فسخ پیش از موعد فقط برای حساب ACTIVE مجاز است.","DEPOSIT_ACCOUNT.ACCOUNT_STATUS_CODE",a.status());
        String approver=required(request.approverUserId(),"APPROVER_USER_ID"),org=required(request.orgUnitCode(),"ORG_UNIT_CODE"),settlement=required(request.settlementAccountReference(),"SETTLEMENT_ACCOUNT_REFERENCE");makerChecker(actor,approver);
        BigDecimal rate=request.earlyTerminationRate();if(rate==null||rate.signum()<0||rate.compareTo(BigDecimal.valueOf(100))>0)throw new IllegalArgumentException("EARLY_TERMINATION_RATE باید بین صفر و 100 باشد.");rate=rate.setScale(6,RoundingMode.HALF_UP);
        BigDecimal accrued=t.principalAmount().multiply(rate).divide(BigDecimal.valueOf(1200),4,RoundingMode.HALF_UP);BigDecimal adjustment=accrued.multiply(new BigDecimal("0.15")).setScale(4,RoundingMode.HALF_UP).negate();BigDecimal tax=BigDecimal.ZERO.setScale(4),fee=BigDecimal.ZERO.setScale(4);BigDecimal net=t.principalAmount().add(accrued).add(adjustment).subtract(tax).subtract(fee).setScale(4,RoundingMode.HALF_UP);if(net.signum()<=0)throw lifecycle("خالص تسویه فسخ پیش از موعد باید مثبت باشد.","DEPOSIT_TERM_EARLY_TERMINATION.NET_SETTLEMENT_AMOUNT",net.toPlainString());
        LocalDate dt=request.terminationDate()==null?LocalDate.now(ZoneOffset.UTC):request.terminationDate();String h=hash("EARLY_TERM|"+accountId+"|"+dt+"|"+settlement+"|"+rate.toPlainString()+"|"+approver);if(replayOrClaim(idempotencyKey,accountId,"TERM_EARLY_TERMINATION_REQUEST",h,actor,correlationId))return new TermActionResponse(state(accountId),parseResult(idempotencyKey,"EARLY:"),true);
        long id=repository.next("SEQ_DEPOSIT_TERM_EARLY_TERMINATION");var closure=closureService.requestClosure(accountId,new ClosureRequest("EARLY_TERMINATION","TERM_EARLY_TERMINATION",dt,settlement,approver,org),actor,correlationId,childKey128(idempotencyKey,"EARLY-CLOSURE"));Long approval=closure.closure().approvalRequestId();
        repository.insertEarlyTermination(id,t.termContractId(),accountId,dt,t.principalAmount(),accrued,rate,adjustment,tax,fee,net,Objects.requireNonNull(approval),actor);repository.insertCalculatedSettlement(repository.next("SEQ_DEPOSIT_TERM_SETTLEMENT"),t.termContractId(),"EARLY_TERMINATION",t.principalAmount(),accrued,adjustment,tax,fee,net,settlement,actor);repository.completeIdempotency(idempotencyKey,"EARLY:"+id);return new TermActionResponse(state(accountId),id,false);
    }

    @Transactional
    public TermActionResponse executeEarlyTermination(long accountId,long id,String actor,String correlationId,String idempotencyKey){
        AccountRow a=requireTermAccount(accountId,true);TermLock t=requireTerm(accountId);EarlyTermination e=early(accountId,id);String h=hash("EARLY_EXECUTE|"+accountId+"|"+id);if(replayOrClaim(idempotencyKey,accountId,"TERM_EARLY_TERMINATION_EXECUTE",h,actor,correlationId))return new TermActionResponse(state(accountId),id,true);
        if(!"ACTIVE".equals(upper(a.status())))throw lifecycle("فسخ پیش از موعد فقط روی حساب ACTIVE قابل اجرا است.","DEPOSIT_ACCOUNT.ACCOUNT_STATUS_CODE",a.status());if(!"REQUESTED".equals(upper(e.statusCode())))throw lifecycle("Early Termination در وضعیت قابل اجرا نیست.","DEPOSIT_TERM_EARLY_TERMINATION.STATUS_CODE",e.statusCode());if(!"APPROVED".equals(upper(e.closureStatusCode())))throw lifecycle("Controlled Closure مربوط به Early Termination باید APPROVED باشد.","DEPOSIT_ACCOUNT_CLOSURE.CLOSURE_STATUS_CODE",e.closureStatusCode());
        ApprovalRow approval=repository.approval(Objects.requireNonNull(e.approvalRequestId())).orElseThrow(()->lifecycle("Approval فسخ پیش از موعد یافت نشد.","DEPOSIT_OPERATION_APPROVAL_REQUEST.APPROVAL_REQUEST_ID",String.valueOf(e.approvalRequestId())));if(!"APPROVED".equals(upper(approval.approvalStatus())))throw lifecycle("Approval فسخ پیش از موعد تأیید نشده است.","DEPOSIT_OPERATION_APPROVAL_REQUEST.APPROVAL_STATUS_CODE",approval.approvalStatus());
        TermSettlement settlement=repository.settlements(accountId).stream().filter(x->"EARLY_TERMINATION".equals(upper(x.settlementTypeCode()))&&"CALCULATED".equals(upper(x.statusCode()))).findFirst().orElseThrow(()->lifecycle("Settlement محاسبه‌شده فسخ یافت نشد.","DEPOSIT_TERM_SETTLEMENT.STATUS_CODE","CALCULATED"));
        SettlementAccount target=repository.settlementAccountByReference(required(settlement.destinationAccountReference(),"SETTLEMENT_ACCOUNT_REFERENCE")).orElseThrow(()->lifecycle("حساب مقصد داخلی فسخ پیش از موعد یافت نشد.","DEPOSIT_TERM_SETTLEMENT.DESTINATION_ACCOUNT_REFERENCE",settlement.destinationAccountReference()));validateSettlementTarget(accountId,a,target);
        BigDecimal principal=nz(e.principalAmount()),profit=nz(e.accruedProfitAmount()),adjustment=nz(e.adjustmentAmount()),tax=nz(e.taxAmount()),fee=nz(e.feeAmount()),net=nz(e.netSettlementAmount());List<DerivedTransactionLeg> legs=settlementLegs(accountId,target,principal,profit,adjustment,tax,fee,net,"EARLY_TERMINATION:"+id);
        var tx=transactionService.postDerived(new DerivedTransactionRequest(accountId,"TERM_EARLY_TERMINATION",net,a.currencyCode(),e.terminationDate(),LocalDate.now(ZoneOffset.UTC),"DEBIT","EARLY_TERMINATION:"+id,"SOURCE_APPROVAL",approval.requestedByUserId(),approval.approverUserId(),"TERM_EARLY_TERMINATION_APPROVED",legs),actor,correlationId,childKey(idempotencyKey,"EARLY-TX"));long txId=tx.transaction().transaction().transactionId();
        if(repository.executeEarlyTermination(id,t.termContractId(),txId,actor)!=1)throw lifecycle("اجرای Early Termination ناموفق بود.","DEPOSIT_TERM_EARLY_TERMINATION.STATUS_CODE",e.statusCode());if(repository.markCalculatedSettlementPosted(t.termContractId(),"EARLY_TERMINATION",txId,actor)!=1)throw lifecycle("Settlement فسخ برای POST شدن یافت نشد.","DEPOSIT_TERM_SETTLEMENT.STATUS_CODE","CALCULATED");
        closureService.executePreSettledClosure(accountId,Objects.requireNonNull(e.closureId()),"TX-"+txId,actor,correlationId,childKey128(idempotencyKey,"EARLY-CLOSURE-EXECUTE"));repository.completeIdempotency(idempotencyKey,"EARLY:"+id);return new TermActionResponse(state(accountId),id,false);
    }

    private TermOperationsView state(long accountId){return new TermOperationsView(repository.term(accountId).orElseThrow(()->lifecycle("قرارداد مدت‌دار برای حساب یافت نشد.","DEPOSIT_TERM_CONTRACT","missing")),repository.maturityEvents(accountId),repository.renewals(accountId),repository.partials(accountId),repository.conversions(accountId),repository.earlyTerminations(accountId),repository.settlements(accountId));}
    private AccountRow requireTermAccount(long accountId,boolean lock){AccountRow a=repository.account(accountId,lock).orElseThrow(()->new DepositAccountNotFoundException("حساب سپرده با شناسه "+accountId+" یافت نشد."));if(!TERM_FAMILIES.contains(upper(a.productFamilyCode())))throw lifecycle("عملیات 11F فقط برای سپرده کوتاه‌مدت/بلندمدت مجاز است.","PRODUCT_FAMILY_CODE",a.productFamilyCode());return a;}
    private TermLock requireTerm(long accountId){return repository.lockTerm(accountId).orElseThrow(()->lifecycle("قرارداد مدت‌دار فعال یافت نشد؛ migration فاز 11F را اجرا کنید.","DEPOSIT_TERM_CONTRACT.ACCOUNT_ID",String.valueOf(accountId)));}
    private void requireTermProduct(long pv){String f=repository.productFamily(pv).orElseThrow(()->new IllegalArgumentException("Product Version مقصد یافت نشد."));if(!TERM_FAMILIES.contains(upper(f)))throw new IllegalArgumentException("تبدیل/تمدید فقط به محصول SHORT_TERM_DEPOSIT یا LONG_TERM_DEPOSIT مجاز است.");}
    private PartialWithdrawal partial(long aid,long id){return repository.partials(aid).stream().filter(x->x.partialWithdrawalId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Partial Withdrawal یافت نشد."));}
    private Renewal renewal(long aid,long id){return repository.renewals(aid).stream().filter(x->x.termRenewalId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Renewal یافت نشد."));}
    private TermConversion conversion(long aid,long id){return repository.conversions(aid).stream().filter(x->x.termConversionId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Conversion یافت نشد."));}
    private EarlyTermination early(long aid,long id){return repository.earlyTerminations(aid).stream().filter(x->x.earlyTerminationId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Early Termination یافت نشد."));}
    private SettlementAccount resolveSettlementAccount(TermContract contract,AccountRow source){SettlementAccount target=null;if(contract.maturitySettlementAccountId()!=null)target=repository.settlementAccount(contract.maturitySettlementAccountId()).orElse(null);if(target==null&&trim(contract.maturitySettlementAccountReference())!=null)target=repository.settlementAccountByReference(contract.maturitySettlementAccountReference()).orElse(null);if(target==null)throw lifecycle("حساب مقصد داخلی دستور PAY_TO_ACCOUNT یافت نشد.","DEPOSIT_TERM_CONTRACT.MATURITY_SETTLEMENT_ACCOUNT_REFERENCE",String.valueOf(contract.maturitySettlementAccountReference()));if(contract.maturitySettlementAccountReference()!=null&&!contract.maturitySettlementAccountReference().equals(target.accountNo()))throw lifecycle("شناسه و مرجع حساب مقصد سررسید سازگار نیستند.","DEPOSIT_TERM_CONTRACT.MATURITY_SETTLEMENT_ACCOUNT_REFERENCE",contract.maturitySettlementAccountReference());validateSettlementTarget(contract.accountId(),source,target);return target;}
    private void validateSettlementTarget(long sourceAccountId,AccountRow source,SettlementAccount target){if(target.accountId()==sourceAccountId)throw lifecycle("حساب مقصد Settlement باید با حساب مبدأ متفاوت باشد.","DEPOSIT_ACCOUNT.ACCOUNT_ID",String.valueOf(target.accountId()));if(!"ACTIVE".equals(upper(target.status())))throw lifecycle("حساب مقصد Settlement باید ACTIVE باشد.","DEPOSIT_ACCOUNT.ACCOUNT_STATUS_CODE",target.status());if(!upper(source.currencyCode()).equals(upper(target.currencyCode())))throw lifecycle("ارز حساب مقصد Settlement با حساب مبدأ یکسان نیست.","DEPOSIT_ACCOUNT.CURRENCY_CODE",target.currencyCode());}
    private List<DerivedTransactionLeg> settlementLegs(long sourceAccountId,SettlementAccount target,BigDecimal principal,BigDecimal profit,BigDecimal adjustment,BigDecimal tax,BigDecimal fee,BigDecimal net,String reference){List<DerivedTransactionLeg> legs=new ArrayList<>();legs.add(new DerivedTransactionLeg(sourceAccountId,null,"DEBIT",principal));if(profit.signum()>0)legs.add(new DerivedTransactionLeg(null,"PROFIT_EXPENSE:"+reference,"DEBIT",profit));if(adjustment.signum()>0)legs.add(new DerivedTransactionLeg(null,"ADJUSTMENT_EXPENSE:"+reference,"DEBIT",adjustment));else if(adjustment.signum()<0)legs.add(new DerivedTransactionLeg(null,"ADJUSTMENT_INCOME:"+reference,"CREDIT",adjustment.abs()));if(tax.signum()>0)legs.add(new DerivedTransactionLeg(null,"TAX_PAYABLE:"+reference,"CREDIT",tax));if(fee.signum()>0)legs.add(new DerivedTransactionLeg(null,"FEE_INCOME:"+reference,"CREDIT",fee));legs.add(new DerivedTransactionLeg(target.accountId(),target.accountNo(),"CREDIT",net));BigDecimal debits=legs.stream().filter(x->"DEBIT".equals(x.debitCreditCode())).map(DerivedTransactionLeg::amount).reduce(BigDecimal.ZERO,BigDecimal::add),credits=legs.stream().filter(x->"CREDIT".equals(x.debitCreditCode())).map(DerivedTransactionLeg::amount).reduce(BigDecimal.ZERO,BigDecimal::add);if(debits.compareTo(credits)!=0)throw lifecycle("مولفه‌های Settlement تراز نیستند.","DEPOSIT_TERM_SETTLEMENT.NET_AMOUNT","debit="+debits+", credit="+credits);return legs;}
    private static LocalDate advanceMaturity(LocalDate maturity,long termValue,String termUnit){if(termValue<=0)throw new IllegalArgumentException("TERM_VALUE باید مثبت باشد.");return switch(upper(termUnit)){case "DAY"->maturity.plusDays(termValue);case "MONTH"->maturity.plusMonths(termValue);case "YEAR"->maturity.plusYears(termValue);default->throw new IllegalArgumentException("TERM_UNIT_CODE پشتیبانی نمی‌شود: "+termUnit);};}
    private static String policyActor(String requester,String preferred){return preferred.equalsIgnoreCase(requester)?preferred+".authorizer":preferred;}
    private static String childKey(String base,String suffix){String x=base+"-"+suffix;return x.length()<=80?x:hash(base+"|"+suffix);}
    private static String childKey128(String base,String suffix){String x=base+"-"+suffix;return x.length()<=128?x:hash(base+"|"+suffix);}
    private static BigDecimal nz(BigDecimal v){return v==null?BigDecimal.ZERO.setScale(4):v;}
    private void makerChecker(String maker,String checker){if(maker.equals(checker))throw new IllegalArgumentException("Maker و Approver باید متفاوت باشند.");}
    private boolean replayOrClaim(String key,long accountId,String operation,String hash,String actor,String corr){if(key==null||key.isBlank())throw new IllegalArgumentException("X-Idempotency-Key الزامی است.");var x=repository.findIdempotency(key);if(x.isPresent()){IdempotencyRow r=x.get();if(!Objects.equals(r.accountId(),accountId)||!operation.equals(r.operationType())||!hash.equals(r.payloadHash()))throw new IllegalArgumentException("Idempotency Key با درخواست دیگری استفاده شده است.");if("COMPLETED".equals(r.processingStatus()))return true;throw lifecycle("درخواست با همین Idempotency Key در حال پردازش است.","DEPOSIT_OPERATION_IDEMPOTENCY.PROCESSING_STATUS_CODE",r.processingStatus());}repository.insertIdempotency(key,accountId,operation,hash,actor,corr);return false;}
    private long parseResult(String key,String prefix){String ref=repository.findIdempotency(key).orElseThrow().resultReference();if(ref==null||!ref.startsWith(prefix))throw new IllegalArgumentException("Idempotency result نامعتبر است.");return Long.parseLong(ref.substring(prefix.length()));}
    private static String approvalKey(String key){return key.length()<=118?key+"-APPROVAL":key.substring(0,118)+"-APPROVAL";}
    private static String required(String s,String field){String v=trim(s);if(v==null)throw new IllegalArgumentException(field+" الزامی است.");return v;}
    private static String trim(String s){return s==null||s.isBlank()?null:s.trim();}private static String upper(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);}
    private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static DepositAccountLifecycleException lifecycle(String msg,String k,String v){return new DepositAccountLifecycleException(msg,Map.of(k,Objects.toString(v,"null")));}
